      "name": "NC Long-Term Care Ombudsman Program",
      "shortName": "NC Ombudsman",
      "tagline": "Free advocacy when your loved one faces problems with their nursing home, assisted living, or care facility.",
      "programType": "resource",
      "complexity": "simple",
